INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "昭宗改名晔", "start_year": 889, "end_year": 889, "time_original": "889年十一月", "dynasty": "唐", "description": "昭宗改名晔；本次改名仍归既有李杰人物。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "ae81144b-1b65-510a-9e00-355623fbbc37"}, {"title": "昭宗允宦官服剑佩参与祭祀", "start_year": 889, "end_year": 889, "time_original": "889年十一月；圆丘祭祀前", "dynasty": "唐", "description": "昭宗命有司制法服，孔纬与谏官、礼官反对；昭宗手札承认所论得当，但主张从权，宦官遂服剑佩侍祠。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "3f81bfee-f37d-50a5-9ee9-551df194e758"}, {"title": "昭宗祀圆丘并大赦", "start_year": 889, "end_year": 889, "time_original": "889年十一月己酉", "dynasty": "唐", "description": "昭宗祭祀圆丘，赦天下。", "phases": [], "location_name": "圆丘", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4ad5015c-cd5c-50ed-ba5e-2df7057b8f21"}, {"title": "昭宗即位前后与杨复恭权力矛盾", "start_year": null, "end_year": null, "time_original": "在藩邸及即位后；具体年日未逐事确定", "dynasty": "唐", "description": "《通鉴》追叙昭宗在藩邸时厌恶宦官，即位后对杨复恭恃援立之功的行为不平，政事多与宰相谋议；孔纬、张浚劝其仿大中故事抑制宦官权力。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "5139542e-856c-579b-bd0e-01f3c8e577b5"}, {"title": "孔纬当廷批评杨复恭蓄假子", "start_year": null, "end_year": null, "time_original": "昭宗即位后他日；具体年日未载", "dynasty": "唐", "description": "孔纬当昭宗面批评杨复恭乘肩舆至前殿、蓄壮士为假子并令掌禁兵或方镇，称其有将反之迹；杨复恭辩称为收士心卫国家，昭宗追问为何不使假子姓李。", "phases": [], "location_name": "太极殿", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4313f055-4403-5beb-9335-2e51cefa777b"}, {"title": "昭宗赐杨守立姓名李顺节", "start_year": null, "end_year": null, "time_original": "昭宗即位后；具体年日未载", "dynasty": "唐", "description": "昭宗担忧杨守立作乱，要求杨复恭使其入侍；杨复恭引见杨守立，昭宗赐姓名李顺节，并使掌六军管钥。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "6aa77135-f8aa-5c18-967d-9f344afc00f1"}, {"title": "李顺节升天武都头领镇海节度使", "start_year": null, "end_year": null, "time_original": "赐名后不期年，俄；具体年日未载", "dynasty": "唐", "description": "李顺节获赐名后未满一年升至天武都头，领镇海节度使，随后加同平章事。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "76a74215-2e01-59e3-a5e2-7bba339228fa"}, {"title": "孔纬拒集百僚见李顺节", "start_year": null, "end_year": null, "time_original": "李顺节加官谢日及他日；具体年日未载", "dynasty": "唐", "description": "李顺节加官谢日，台吏申请其班见百僚，孔纬判不集。李顺节后到中书流露不悦并提起此事，孔纬以宰相师长百僚回应，李顺节不敢再言。", "phases": [], "location_name": "中书", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "6362697a-796a-5693-833f-69af5cff58a1"}, {"title": "孔纬阻朱全忠兼领盐铁", "start_year": 889, "end_year": 889, "time_original": "889年十一月后条；具体日未载", "dynasty": "唐", "description": "朱全忠请求兼领盐铁，孔纬坚持反对，并向进奏吏表示朱全忠若要此职须兴兵；朱全忠遂止。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "6307cb83-5f14-5bc8-af55-012bb112c108"}, {"title": "田頵地道入常州擒杜稜", "start_year": 889, "end_year": 889, "time_original": "889年十一月后条；具体日未载", "dynasty": "唐", "description": "田頵攻常州，通过地道于夜间入城，军兵出于制置使杜稜寝室，俘获杜稜，并以兵驻守常州。", "phases": [], "location_name": "常州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "3b3d3175-d46f-5f41-b00c-0de0601706a5"}, {"title": "庞师古自颍上进击孙儒", "start_year": 889, "end_year": 889, "time_original": "889年十一月后条；具体日未载", "dynasty": "唐", "description": "朱全忠遣庞师古率兵自颍上趋淮南，进击孙儒。", "phases": [], "location_name": "颍上、淮南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "b44ed005-7801-5b1a-98d1-801134a870ea"}, {"title": "王建败山行章宋行能于广都", "start_year": 889, "end_year": 889, "time_original": "889年十二月甲子", "dynasty": "唐", "description": "王建在广都击败山行章及西川骑将宋行能。宋行能返回成都，山行章退守眉州。", "phases": [], "location_name": "广都、成都、眉州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "777a25f4-7d02-519d-bfdb-c30d1ccb932b"}, {"title": "山行章向王建请降", "start_year": 889, "end_year": 889, "time_original": "889年十二月壬申", "dynasty": "唐", "description": "山行章向王建请求投降。", "phases": [], "location_name": "眉州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f7930c9f-33ed-5cef-b1d6-523cc0be0cb5"}, {"title": "孙儒自广陵渡江", "start_year": 889, "end_year": 889, "time_original": "889年十二月戊寅", "dynasty": "唐", "description": "孙儒自广陵引兵渡江。", "phases": [], "location_name": "广陵、江", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "5ff64c7b-f4ca-5a32-b507-f8ffde2f54bb"}, {"title": "孙儒逐田頵取常州，刘建锋守城", "start_year": 889, "end_year": 889, "time_original": "889年十二月壬午", "dynasty": "唐", "description": "孙儒驱逐田頵，攻取常州，以刘建锋守之，随后返回广陵。", "phases": [], "location_name": "常州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ea83d9a1-e033-571c-a595-d791f7ac823b"}, {"title": "刘建锋逐成及取润州", "start_year": 889, "end_year": 889, "time_original": "889年十二月条；孙儒还广陵后", "dynasty": "唐", "description": "孙儒返回广陵后，刘建锋又驱逐成及，攻取润州。", "phases": [], "location_name": "润州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "25576fc8-a0cc-5297-8f92-450db9214961"}, {"title": "刘巨容襄阳得炼金方的追叙", "start_year": null, "end_year": null, "time_original": "刘巨容任山南东道节度使时；具体年未载", "dynasty": "唐", "description": "《通鉴》追叙刘巨容在襄阳时，申屠生传授所谓烧药为黄金的方法；田令孜之弟途经襄阳，刘巨容向其展示金。", "phases": [], "location_name": "襄阳", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "352985b6-8c20-5acb-9383-cdd820da2ff7"}, {"title": "田令孜求刘巨容炼金方被拒", "start_year": null, "end_year": null, "time_original": "刘巨容寓居成都后；具体年未载", "dynasty": "唐", "description": "刘巨容寓居成都后，田令孜向其索取炼金方法，刘巨容不予，田令孜记恨。", "phases": [], "location_name": "成都", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "bacd78d0-0ddf-52b8-aca9-1c272ad17f84"}, {"title": "田令孜杀刘巨容并灭其族", "start_year": 889, "end_year": 889, "time_original": "889年；原文是岁", "dynasty": "唐", "description": "《通鉴》记田令孜在本年杀刘巨容并灭其族。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "602eefbf-f124-5b0f-9f7e-00845fd9ea4d"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

