INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "昭宗改名晔；本次改名仍归既有李杰人物。", "citation": "卷258·龙纪元年（889）·zztj-v258-y0889-p017·原文件第22行", "note": "原文：十一月，上改名晔。；核对说明：姓名变化不另建人物，原先李敏、李杰及唐昭宗沿用同一key。", "status": "draft", "id": "c549cdfa-1111-5dd8-b8d9-d7df8eb65dd3", "subject_id": "ae81144b-1b65-510a-9e00-355623fbbc37", "source_id": "05c9225a-31fa-5b09-b469-321e20f26115"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "889年十一月", "citation": "卷258·龙纪元年（889）·zztj-v258-y0889-p017·原文件第22行", "note": "原文：十一月，上改名晔。；核对说明：姓名变化不另建人物，原先李敏、李杰及唐昭宗沿用同一key。", "status": "draft", "id": "e1010804-b076-53b6-bd3b-0e7e934c61e9", "subject_id": "ae81144b-1b65-510a-9e00-355623fbbc37", "source_id": "05c9225a-31fa-5b09-b469-321e20f26115"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记李杰：改名者。", "citation": "卷258·龙纪元年（889）·zztj-v258-y0889-p017·原文件第22行", "note": "原文：十一月，上改名晔。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "c3a89639-a7fa-5f6c-bfed-0c284b9f847d", "subject_id": "48935190-c754-5bda-bdcd-382c77cb2de0", "source_id": "05c9225a-31fa-5b09-b469-321e20f26115"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "唐昭宗：改名者。", "citation": "卷258·龙纪元年（889）·zztj-v258-y0889-p017·原文件第22行", "note": "原文：十一月，上改名晔。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "9a7d3e16-2625-5ed3-8d9c-75cd8854eb66", "subject_id": "8500a958-7d28-5a38-874c-4a7d5134e25a", "source_id": "05c9225a-31fa-5b09-b469-321e20f26115"}, {"subject_table": "person", "field_path": "aliases", "claim_text": "昭宗于889年十一月改名晔，李晔为同一人物的后用名。", "citation": "卷258·龙纪元年（889）·zztj-v258-y0889-p017·原文件第22行", "note": "原文：十一月，上改名晔。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "d934d672-8b78-5ef7-9519-7e3d71f1643f", "subject_id": "48935190-c754-5bda-bdcd-382c77cb2de0", "source_id": "05c9225a-31fa-5b09-b469-321e20f26115"}, {"subject_table": "event", "field_path": "description", "claim_text": "昭宗命有司制法服，孔纬与谏官、礼官反对；昭宗手札承认所论得当，但主张从权，宦官遂服剑佩侍祠。", "citation": "卷258·龙纪元年（889）·zztj-v258-y0889-p018·原文件第23行", "note": "原文：上将祀圆丘。故事，中尉、枢密皆衤癸衫侍从。僖宗之世，已具襕笏。至是，又令有司制法服，孔纬及谏官、礼官皆以为不可，上出手札谕之曰：“卿等所论至当。事有从权，勿以小瑕，遂妨大礼。”于是宦官始服剑佩侍祠。己酉，祀圆丘，赦天下。上在籓邸，素疾宦官，及即位，杨复恭恃援立功，所为多不法，上意不平。政事多谋于宰相，孔纬、张浚劝上举大中故事，抑宦者权。复恭常乘肩舆至太极殿。他日，上与宰相言及四方反者，孔纬曰：“陛下左右有将反者，况四方乎！”上矍然问之，纬指复恭曰：“复恭陛下家奴，乃肩舆造前殿，多养壮士为假子，使典禁兵，或为方镇，非反而何！”复恭曰：“子壮士，欲以收士心，卫国家，岂反邪！”上曰：“卿欲卫国家，何不使姓李而姓杨乎？”复恭无以对。复恭假子天威军使杨守立，本姓胡，名弘立，勇冠六军，人皆畏之。上欲讨复恭，恐守立作乱，谓复恭：“朕欲得卿胡子在左右。”复恭见守立于上，上赐姓名李顺节，使掌六军管钥，不期年，擢至天武都头，领镇海节度使，俄加同平章事。及谢日，台吏申请班见百僚，孔纬判不集。顺节至中书，色不悦。他日，语微及之，纬曰：“宰相师长百僚，于意安乎？”顺节不敢复言。；核对说明：底本“衤癸衫”疑转录残字，保留快照，不猜定具体衣制名称；本事件只记明示的本次制法服与争议。", "status": "draft", "id": "08220e55-4503-5e21-b3d1-62de27057cc9", "subject_id": "3f81bfee-f37d-50a5-9ee9-551df194e758", "source_id": "05c9225a-31fa-5b09-b469-321e20f26115"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "889年十一月；圆丘祭祀前", "citation": "卷258·龙纪元年（889）·zztj-v258-y0889-p018·原文件第23行", "note": "原文：上将祀圆丘。故事，中尉、枢密皆衤癸衫侍从。僖宗之世，已具襕笏。至是，又令有司制法服，孔纬及谏官、礼官皆以为不可，上出手札谕之曰：“卿等所论至当。事有从权，勿以小瑕，遂妨大礼。”于是宦官始服剑佩侍祠。己酉，祀圆丘，赦天下。上在籓邸，素疾宦官，及即位，杨复恭恃援立功，所为多不法，上意不平。政事多谋于宰相，孔纬、张浚劝上举大中故事，抑宦者权。复恭常乘肩舆至太极殿。他日，上与宰相言及四方反者，孔纬曰：“陛下左右有将反者，况四方乎！”上矍然问之，纬指复恭曰：“复恭陛下家奴，乃肩舆造前殿，多养壮士为假子，使典禁兵，或为方镇，非反而何！”复恭曰：“子壮士，欲以收士心，卫国家，岂反邪！”上曰：“卿欲卫国家，何不使姓李而姓杨乎？”复恭无以对。复恭假子天威军使杨守立，本姓胡，名弘立，勇冠六军，人皆畏之。上欲讨复恭，恐守立作乱，谓复恭：“朕欲得卿胡子在左右。”复恭见守立于上，上赐姓名李顺节，使掌六军管钥，不期年，擢至天武都头，领镇海节度使，俄加同平章事。及谢日，台吏申请班见百僚，孔纬判不集。顺节至中书，色不悦。他日，语微及之，纬曰：“宰相师长百僚，于意安乎？”顺节不敢复言。；核对说明：底本“衤癸衫”疑转录残字，保留快照，不猜定具体衣制名称；本事件只记明示的本次制法服与争议。", "status": "draft", "id": "4fe9932c-4942-5f32-923a-90f4d91648f2", "subject_id": "3f81bfee-f37d-50a5-9ee9-551df194e758", "source_id": "05c9225a-31fa-5b09-b469-321e20f26115"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "唐昭宗：准许法服者。", "citation": "卷258·龙纪元年（889）·zztj-v258-y0889-p018·原文件第23行", "note": "原文：上将祀圆丘。故事，中尉、枢密皆衤癸衫侍从。僖宗之世，已具襕笏。至是，又令有司制法服，孔纬及谏官、礼官皆以为不可，上出手札谕之曰：“卿等所论至当。事有从权，勿以小瑕，遂妨大礼。”于是宦官始服剑佩侍祠。己酉，祀圆丘，赦天下。上在籓邸，素疾宦官，及即位，杨复恭恃援立功，所为多不法，上意不平。政事多谋于宰相，孔纬、张浚劝上举大中故事，抑宦者权。复恭常乘肩舆至太极殿。他日，上与宰相言及四方反者，孔纬曰：“陛下左右有将反者，况四方乎！”上矍然问之，纬指复恭曰：“复恭陛下家奴，乃肩舆造前殿，多养壮士为假子，使典禁兵，或为方镇，非反而何！”复恭曰：“子壮士，欲以收士心，卫国家，岂反邪！”上曰：“卿欲卫国家，何不使姓李而姓杨乎？”复恭无以对。复恭假子天威军使杨守立，本姓胡，名弘立，勇冠六军，人皆畏之。上欲讨复恭，恐守立作乱，谓复恭：“朕欲得卿胡子在左右。”复恭见守立于上，上赐姓名李顺节，使掌六军管钥，不期年，擢至天武都头，领镇海节度使，俄加同平章事。及谢日，台吏申请班见百僚，孔纬判不集。顺节至中书，色不悦。他日，语微及之，纬曰：“宰相师长百僚，于意安乎？”顺节不敢复言。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "f7b91561-a1fb-5ad5-bdc8-f68a66603362", "subject_id": "1c349319-174f-57c0-b468-9c3a310d6b8a", "source_id": "05c9225a-31fa-5b09-b469-321e20f26115"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记孔纬：反对者。", "citation": "卷258·龙纪元年（889）·zztj-v258-y0889-p018·原文件第23行", "note": "原文：上将祀圆丘。故事，中尉、枢密皆衤癸衫侍从。僖宗之世，已具襕笏。至是，又令有司制法服，孔纬及谏官、礼官皆以为不可，上出手札谕之曰：“卿等所论至当。事有从权，勿以小瑕，遂妨大礼。”于是宦官始服剑佩侍祠。己酉，祀圆丘，赦天下。上在籓邸，素疾宦官，及即位，杨复恭恃援立功，所为多不法，上意不平。政事多谋于宰相，孔纬、张浚劝上举大中故事，抑宦者权。复恭常乘肩舆至太极殿。他日，上与宰相言及四方反者，孔纬曰：“陛下左右有将反者，况四方乎！”上矍然问之，纬指复恭曰：“复恭陛下家奴，乃肩舆造前殿，多养壮士为假子，使典禁兵，或为方镇，非反而何！”复恭曰：“子壮士，欲以收士心，卫国家，岂反邪！”上曰：“卿欲卫国家，何不使姓李而姓杨乎？”复恭无以对。复恭假子天威军使杨守立，本姓胡，名弘立，勇冠六军，人皆畏之。上欲讨复恭，恐守立作乱，谓复恭：“朕欲得卿胡子在左右。”复恭见守立于上，上赐姓名李顺节，使掌六军管钥，不期年，擢至天武都头，领镇海节度使，俄加同平章事。及谢日，台吏申请班见百僚，孔纬判不集。顺节至中书，色不悦。他日，语微及之，纬曰：“宰相师长百僚，于意安乎？”顺节不敢复言。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "53b029bb-534f-519f-8f4a-e6784bc2bfc9", "subject_id": "07254f47-15dc-55d0-b38f-bfefa4def94e", "source_id": "05c9225a-31fa-5b09-b469-321e20f26115"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "孔纬：反对者。", "citation": "卷258·龙纪元年（889）·zztj-v258-y0889-p018·原文件第23行", "note": "原文：上将祀圆丘。故事，中尉、枢密皆衤癸衫侍从。僖宗之世，已具襕笏。至是，又令有司制法服，孔纬及谏官、礼官皆以为不可，上出手札谕之曰：“卿等所论至当。事有从权，勿以小瑕，遂妨大礼。”于是宦官始服剑佩侍祠。己酉，祀圆丘，赦天下。上在籓邸，素疾宦官，及即位，杨复恭恃援立功，所为多不法，上意不平。政事多谋于宰相，孔纬、张浚劝上举大中故事，抑宦者权。复恭常乘肩舆至太极殿。他日，上与宰相言及四方反者，孔纬曰：“陛下左右有将反者，况四方乎！”上矍然问之，纬指复恭曰：“复恭陛下家奴，乃肩舆造前殿，多养壮士为假子，使典禁兵，或为方镇，非反而何！”复恭曰：“子壮士，欲以收士心，卫国家，岂反邪！”上曰：“卿欲卫国家，何不使姓李而姓杨乎？”复恭无以对。复恭假子天威军使杨守立，本姓胡，名弘立，勇冠六军，人皆畏之。上欲讨复恭，恐守立作乱，谓复恭：“朕欲得卿胡子在左右。”复恭见守立于上，上赐姓名李顺节，使掌六军管钥，不期年，擢至天武都头，领镇海节度使，俄加同平章事。及谢日，台吏申请班见百僚，孔纬判不集。顺节至中书，色不悦。他日，语微及之，纬曰：“宰相师长百僚，于意安乎？”顺节不敢复言。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "d8e00794-1d2e-52ce-91c3-7fdf3ab6f339", "subject_id": "5f18482f-01d4-5b86-a13d-b263d170199d", "source_id": "05c9225a-31fa-5b09-b469-321e20f26115"}, {"subject_table": "event", "field_path": "description", "claim_text": "昭宗祭祀圆丘，赦天下。", "citation": "卷258·龙纪元年（889）·zztj-v258-y0889-p018·原文件第23行", "note": "原文：上将祀圆丘。故事，中尉、枢密皆衤癸衫侍从。僖宗之世，已具襕笏。至是，又令有司制法服，孔纬及谏官、礼官皆以为不可，上出手札谕之曰：“卿等所论至当。事有从权，勿以小瑕，遂妨大礼。”于是宦官始服剑佩侍祠。己酉，祀圆丘，赦天下。上在籓邸，素疾宦官，及即位，杨复恭恃援立功，所为多不法，上意不平。政事多谋于宰相，孔纬、张浚劝上举大中故事，抑宦者权。复恭常乘肩舆至太极殿。他日，上与宰相言及四方反者，孔纬曰：“陛下左右有将反者，况四方乎！”上矍然问之，纬指复恭曰：“复恭陛下家奴，乃肩舆造前殿，多养壮士为假子，使典禁兵，或为方镇，非反而何！”复恭曰：“子壮士，欲以收士心，卫国家，岂反邪！”上曰：“卿欲卫国家，何不使姓李而姓杨乎？”复恭无以对。复恭假子天威军使杨守立，本姓胡，名弘立，勇冠六军，人皆畏之。上欲讨复恭，恐守立作乱，谓复恭：“朕欲得卿胡子在左右。”复恭见守立于上，上赐姓名李顺节，使掌六军管钥，不期年，擢至天武都头，领镇海节度使，俄加同平章事。及谢日，台吏申请班见百僚，孔纬判不集。顺节至中书，色不悦。他日，语微及之，纬曰：“宰相师长百僚，于意安乎？”顺节不敢复言。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "eea0c66c-1351-56e0-81cf-43d2030914af", "subject_id": "4ad5015c-cd5c-50ed-ba5e-2df7057b8f21", "source_id": "05c9225a-31fa-5b09-b469-321e20f26115"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "889年十一月己酉", "citation": "卷258·龙纪元年（889）·zztj-v258-y0889-p018·原文件第23行", "note": "原文：上将祀圆丘。故事，中尉、枢密皆衤癸衫侍从。僖宗之世，已具襕笏。至是，又令有司制法服，孔纬及谏官、礼官皆以为不可，上出手札谕之曰：“卿等所论至当。事有从权，勿以小瑕，遂妨大礼。”于是宦官始服剑佩侍祠。己酉，祀圆丘，赦天下。上在籓邸，素疾宦官，及即位，杨复恭恃援立功，所为多不法，上意不平。政事多谋于宰相，孔纬、张浚劝上举大中故事，抑宦者权。复恭常乘肩舆至太极殿。他日，上与宰相言及四方反者，孔纬曰：“陛下左右有将反者，况四方乎！”上矍然问之，纬指复恭曰：“复恭陛下家奴，乃肩舆造前殿，多养壮士为假子，使典禁兵，或为方镇，非反而何！”复恭曰：“子壮士，欲以收士心，卫国家，岂反邪！”上曰：“卿欲卫国家，何不使姓李而姓杨乎？”复恭无以对。复恭假子天威军使杨守立，本姓胡，名弘立，勇冠六军，人皆畏之。上欲讨复恭，恐守立作乱，谓复恭：“朕欲得卿胡子在左右。”复恭见守立于上，上赐姓名李顺节，使掌六军管钥，不期年，擢至天武都头，领镇海节度使，俄加同平章事。及谢日，台吏申请班见百僚，孔纬判不集。顺节至中书，色不悦。他日，语微及之，纬曰：“宰相师长百僚，于意安乎？”顺节不敢复言。；核对说明：干支日未换算公历日。", "status": "draft", "id": "8f92626e-ee50-54c7-acdf-eefd49424c72", "subject_id": "4ad5015c-cd5c-50ed-ba5e-2df7057b8f21", "source_id": "05c9225a-31fa-5b09-b469-321e20f26115"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "唐昭宗：祭祀及赦令者。", "citation": "卷258·龙纪元年（889）·zztj-v258-y0889-p018·原文件第23行", "note": "原文：上将祀圆丘。故事，中尉、枢密皆衤癸衫侍从。僖宗之世，已具襕笏。至是，又令有司制法服，孔纬及谏官、礼官皆以为不可，上出手札谕之曰：“卿等所论至当。事有从权，勿以小瑕，遂妨大礼。”于是宦官始服剑佩侍祠。己酉，祀圆丘，赦天下。上在籓邸，素疾宦官，及即位，杨复恭恃援立功，所为多不法，上意不平。政事多谋于宰相，孔纬、张浚劝上举大中故事，抑宦者权。复恭常乘肩舆至太极殿。他日，上与宰相言及四方反者，孔纬曰：“陛下左右有将反者，况四方乎！”上矍然问之，纬指复恭曰：“复恭陛下家奴，乃肩舆造前殿，多养壮士为假子，使典禁兵，或为方镇，非反而何！”复恭曰：“子壮士，欲以收士心，卫国家，岂反邪！”上曰：“卿欲卫国家，何不使姓李而姓杨乎？”复恭无以对。复恭假子天威军使杨守立，本姓胡，名弘立，勇冠六军，人皆畏之。上欲讨复恭，恐守立作乱，谓复恭：“朕欲得卿胡子在左右。”复恭见守立于上，上赐姓名李顺节，使掌六军管钥，不期年，擢至天武都头，领镇海节度使，俄加同平章事。及谢日，台吏申请班见百僚，孔纬判不集。顺节至中书，色不悦。他日，语微及之，纬曰：“宰相师长百僚，于意安乎？”顺节不敢复言。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "e07082be-9fbb-56d6-8645-691c379ff743", "subject_id": "c0edf4c1-1b18-54d1-963a-a21fac5d17ee", "source_id": "05c9225a-31fa-5b09-b469-321e20f26115"}, {"subject_table": "event", "field_path": "description", "claim_text": "《通鉴》追叙昭宗在藩邸时厌恶宦官，即位后对杨复恭恃援立之功的行为不平，政事多与宰相谋议；孔纬、张浚劝其仿大中故事抑制宦官权力。", "citation": "卷258·龙纪元年（889）·zztj-v258-y0889-p018·原文件第23行", "note": "原文：上将祀圆丘。故事，中尉、枢密皆衤癸衫侍从。僖宗之世，已具襕笏。至是，又令有司制法服，孔纬及谏官、礼官皆以为不可，上出手札谕之曰：“卿等所论至当。事有从权，勿以小瑕，遂妨大礼。”于是宦官始服剑佩侍祠。己酉，祀圆丘，赦天下。上在籓邸，素疾宦官，及即位，杨复恭恃援立功，所为多不法，上意不平。政事多谋于宰相，孔纬、张浚劝上举大中故事，抑宦者权。复恭常乘肩舆至太极殿。他日，上与宰相言及四方反者，孔纬曰：“陛下左右有将反者，况四方乎！”上矍然问之，纬指复恭曰：“复恭陛下家奴，乃肩舆造前殿，多养壮士为假子，使典禁兵，或为方镇，非反而何！”复恭曰：“子壮士，欲以收士心，卫国家，岂反邪！”上曰：“卿欲卫国家，何不使姓李而姓杨乎？”复恭无以对。复恭假子天威军使杨守立，本姓胡，名弘立，勇冠六军，人皆畏之。上欲讨复恭，恐守立作乱，谓复恭：“朕欲得卿胡子在左右。”复恭见守立于上，上赐姓名李顺节，使掌六军管钥，不期年，擢至天武都头，领镇海节度使，俄加同平章事。及谢日，台吏申请班见百僚，孔纬判不集。顺节至中书，色不悦。他日，语微及之，纬曰：“宰相师长百僚，于意安乎？”顺节不敢复言。；核对说明：跨藩邸与即位后的追叙，不一律落在889年；对其行为的评价以书载叙述呈现。", "status": "draft", "id": "cfeb55f8-33f0-5117-9252-ca953cbc7f7b", "subject_id": "5139542e-856c-579b-bd0e-01f3c8e577b5", "source_id": "05c9225a-31fa-5b09-b469-321e20f26115"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "在藩邸及即位后；具体年日未逐事确定", "citation": "卷258·龙纪元年（889）·zztj-v258-y0889-p018·原文件第23行", "note": "原文：上将祀圆丘。故事，中尉、枢密皆衤癸衫侍从。僖宗之世，已具襕笏。至是，又令有司制法服，孔纬及谏官、礼官皆以为不可，上出手札谕之曰：“卿等所论至当。事有从权，勿以小瑕，遂妨大礼。”于是宦官始服剑佩侍祠。己酉，祀圆丘，赦天下。上在籓邸，素疾宦官，及即位，杨复恭恃援立功，所为多不法，上意不平。政事多谋于宰相，孔纬、张浚劝上举大中故事，抑宦者权。复恭常乘肩舆至太极殿。他日，上与宰相言及四方反者，孔纬曰：“陛下左右有将反者，况四方乎！”上矍然问之，纬指复恭曰：“复恭陛下家奴，乃肩舆造前殿，多养壮士为假子，使典禁兵，或为方镇，非反而何！”复恭曰：“子壮士，欲以收士心，卫国家，岂反邪！”上曰：“卿欲卫国家，何不使姓李而姓杨乎？”复恭无以对。复恭假子天威军使杨守立，本姓胡，名弘立，勇冠六军，人皆畏之。上欲讨复恭，恐守立作乱，谓复恭：“朕欲得卿胡子在左右。”复恭见守立于上，上赐姓名李顺节，使掌六军管钥，不期年，擢至天武都头，领镇海节度使，俄加同平章事。及谢日，台吏申请班见百僚，孔纬判不集。顺节至中书，色不悦。他日，语微及之，纬曰：“宰相师长百僚，于意安乎？”顺节不敢复言。；核对说明：跨藩邸与即位后的追叙，不一律落在889年；对其行为的评价以书载叙述呈现。", "status": "draft", "id": "eb3fc4cd-47d8-523d-a1ed-bbd58c8bcd07", "subject_id": "5139542e-856c-579b-bd0e-01f3c8e577b5", "source_id": "05c9225a-31fa-5b09-b469-321e20f26115"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "唐昭宗：与宰相谋议者。", "citation": "卷258·龙纪元年（889）·zztj-v258-y0889-p018·原文件第23行", "note": "原文：上将祀圆丘。故事，中尉、枢密皆衤癸衫侍从。僖宗之世，已具襕笏。至是，又令有司制法服，孔纬及谏官、礼官皆以为不可，上出手札谕之曰：“卿等所论至当。事有从权，勿以小瑕，遂妨大礼。”于是宦官始服剑佩侍祠。己酉，祀圆丘，赦天下。上在籓邸，素疾宦官，及即位，杨复恭恃援立功，所为多不法，上意不平。政事多谋于宰相，孔纬、张浚劝上举大中故事，抑宦者权。复恭常乘肩舆至太极殿。他日，上与宰相言及四方反者，孔纬曰：“陛下左右有将反者，况四方乎！”上矍然问之，纬指复恭曰：“复恭陛下家奴，乃肩舆造前殿，多养壮士为假子，使典禁兵，或为方镇，非反而何！”复恭曰：“子壮士，欲以收士心，卫国家，岂反邪！”上曰：“卿欲卫国家，何不使姓李而姓杨乎？”复恭无以对。复恭假子天威军使杨守立，本姓胡，名弘立，勇冠六军，人皆畏之。上欲讨复恭，恐守立作乱，谓复恭：“朕欲得卿胡子在左右。”复恭见守立于上，上赐姓名李顺节，使掌六军管钥，不期年，擢至天武都头，领镇海节度使，俄加同平章事。及谢日，台吏申请班见百僚，孔纬判不集。顺节至中书，色不悦。他日，语微及之，纬曰：“宰相师长百僚，于意安乎？”顺节不敢复言。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "6f2567fb-e69b-5ec3-9cac-4a644c657016", "subject_id": "5b2d50f9-166b-539a-b07e-4d1a8ef87a31", "source_id": "05c9225a-31fa-5b09-b469-321e20f26115"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记杨复恭：被批评对象。", "citation": "卷258·龙纪元年（889）·zztj-v258-y0889-p018·原文件第23行", "note": "原文：上将祀圆丘。故事，中尉、枢密皆衤癸衫侍从。僖宗之世，已具襕笏。至是，又令有司制法服，孔纬及谏官、礼官皆以为不可，上出手札谕之曰：“卿等所论至当。事有从权，勿以小瑕，遂妨大礼。”于是宦官始服剑佩侍祠。己酉，祀圆丘，赦天下。上在籓邸，素疾宦官，及即位，杨复恭恃援立功，所为多不法，上意不平。政事多谋于宰相，孔纬、张浚劝上举大中故事，抑宦者权。复恭常乘肩舆至太极殿。他日，上与宰相言及四方反者，孔纬曰：“陛下左右有将反者，况四方乎！”上矍然问之，纬指复恭曰：“复恭陛下家奴，乃肩舆造前殿，多养壮士为假子，使典禁兵，或为方镇，非反而何！”复恭曰：“子壮士，欲以收士心，卫国家，岂反邪！”上曰：“卿欲卫国家，何不使姓李而姓杨乎？”复恭无以对。复恭假子天威军使杨守立，本姓胡，名弘立，勇冠六军